# Copies the FBX exports (and their baked textures) generated by Infinigen in WSL into Saved/Infinigen/<category>/,
# where Scripts/import_infinigen_assets.py picks them up. WSL layout: generated/<category>/<Factory>/export_NNN/;
# each FBX is renamed <Factory>_NNN.fbx so the imported assets do not collide.
param([string]$Distro = "Ubuntu-24.04")
$source = "\\wsl.localhost\$Distro\root\makar\generated"
$target = Join-Path $PSScriptRoot "..\..\Saved\Infinigen"
foreach ($category in Get-ChildItem $source -Directory) {
    foreach ($factory in Get-ChildItem $category.FullName -Directory) {
        foreach ($export in Get-ChildItem $factory.FullName -Directory -Filter "export_*") {
            $fbx = Get-ChildItem $export.FullName -Filter *.fbx | Select-Object -First 1
            if (-not $fbx) { continue }
            $name = "$($factory.Name)_$($export.Name -replace '^export_', '')"
            $destination = Join-Path $target "$($category.Name)\$name"
            New-Item -ItemType Directory -Force $destination | Out-Null
            Copy-Item -Recurse -Force "$($export.FullName)\textures" $destination -ErrorAction SilentlyContinue
            Copy-Item -Force $fbx.FullName (Join-Path $destination "$name.fbx")
            "$($category.Name)/$name"
        }
    }
}

# Coconut frond textures for the palm leaf cards (Scripts/infinigen/render_frond_atlas.py).
$frond = "\\wsl.localhost\$Distro\root\makar\frond_atlas"
if (Test-Path "$frond\frond_basecolor.png") {
    New-Item -ItemType Directory -Force (Join-Path $target "frond") | Out-Null
    Copy-Item -Force "$frond\*.png", "$frond\frond.json" (Join-Path $target "frond")
    "frond"
}

# Grass tuft for the grass cards (Scripts/infinigen/render_grass_tuft.py).
$tuft = "\\wsl.localhost\$Distro\root\makar\grass_tuft"
if (Test-Path "$tuft\tuft_basecolor.png") {
    New-Item -ItemType Directory -Force (Join-Path $target "tuft") | Out-Null
    Copy-Item -Force "$tuft\*.png", "$tuft\tuft.json" (Join-Path $target "tuft")
    "tuft"
}

# Ground tiles for the terrain material (Scripts/infinigen/render_ground_tiles.py).
$ground = "\\wsl.localhost\$Distro\root\makar\ground_tiles"
if (Test-Path "$ground\*_basecolor.png") {
    New-Item -ItemType Directory -Force (Join-Path $target "ground") | Out-Null
    Copy-Item -Force "$ground\*.png" (Join-Path $target "ground")
    "ground"
}

# Leaf clusters for the leaf cards of the broadleaf trees and sea grapes (Scripts/infinigen/render_leaf_cluster.py).
$leaves = "\\wsl.localhost\$Distro\root\makar\leaf_atlas"
if (Test-Path "$leaves\*_basecolor.png") {
    New-Item -ItemType Directory -Force (Join-Path $target "leaves") | Out-Null
    Copy-Item -Force "$leaves\*.png" (Join-Path $target "leaves")
    "leaves"
}
